def distance_to_stove(environment, trajectory, r=3.0):
    objs = get_objects_with_property("stove", environment)
    feat = np.zeros(1)
    if not objs:
        return feat
    for i in range(0, len(trajectory) - 1, 2):
        for o in objs:
            d = np.hypot(trajectory[i] - o[0], trajectory[i + 1] - o[1])
            feat += min(d, r)
    return feat / len(objs)

```

